def first_item(values):
    return values[0] if values else None  # O(1)

def total(values):
    answer = 0
    for value in values:  # O(n)
        answer += value
    return answer

numbers = [3, 5, 7, 9]
print(first_item(numbers))
print(total(numbers))

def frequencies(values):
    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    return counts

def is_palindrome(text):
    left, right = 0, len(text) - 1
    while left < right:
        if text[left] != text[right]:
            return False
        left += 1
        right -= 1
    return True

print(frequencies([2, 3, 2, 4, 3, 2]))
print(is_palindrome('level'))

def binary_search(values, target):
    left, right = 0, len(values) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if values[mid] == target:
            return mid
        if values[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

numbers = [2, 5, 8, 12, 16, 23]
print(binary_search(numbers, 12))
print(binary_search(numbers, 7))

def two_sum(values, target):
    seen = {}
    for index, value in enumerate(values):
        needed = target - value
        if needed in seen:
            return [seen[needed], index]
        seen[value] = index
    return []

print(two_sum([2, 7, 11, 15], 9))
print(two_sum([3, 3], 6))
print(two_sum([1, 2], 8))
